// The engine's families: tools that only some stories use (Windows and its
// PowerShell, a Kubernetes cluster, libvirt, CUPS…), kept out of the first
// visit. A family is a module of families/ that registers its commands and
// the functions the rest of the engine calls into (its hooks); it loads with
// the stories that need it, whose module (stories/<id>.ts) imports it, so it
// is there before their chapters run.
//
// What the engine knows of a family's commands without loading it is in
// families.json (generated by `npm run catalogue`, checked by
// tests/catalogue.test.ts): each command's family and its entry (options,
// section, cmdlet…) without the implementation. The table of commands
// (commands/index.ts) holds that entry for the manual, Tab, highlighting and
// availability; running it before its family has loaded throws NeedsLoading
// (the interface loads the family and runs the line again: needs() in
// game.ts loads it first when the line names one of its commands).
//
// Adding a family: its module in families/ (registerFamily with its
// commands and hooks), its loader below, an import in each story module
// that uses it, then `npm run catalogue`. The core never imports a family's
// modules, only their types: `family('windows').runPowerShell(…)`.

import { NeedsLoading } from './loading';
import type { Command } from './commands/index';
import type * as Ansible from './families/ansible';
import type * as Apache from './families/apache';
import type * as Caddy from './families/caddy';
import type * as Cobol from './families/cobol';
import type * as Cups from './families/cups';
import type * as Directory from './families/directory';
import type * as Docker from './families/docker';
import type * as Forge from './families/forge';
import type * as Ha from './families/ha';
import type * as Iac from './families/iac';
import type * as Ibmi from './families/ibmi';
import type * as Inbound from './families/inbound';
import type * as Jq from './families/jq';
import type * as K8s from './families/k8s';
import type * as Lftp from './families/lftp';
import type * as Libvirt from './families/libvirt';
import type * as Luks from './families/luks';
import type * as Mariadb from './families/mariadb';
import type * as Nut from './families/nut';
import type * as Objects from './families/objects';
import type * as Openbao from './families/openbao';
import type * as Postfix from './families/postfix';
import type * as Postgres from './families/postgres';
import type * as Prometheus from './families/prometheus';
import type * as Rhel from './families/rhel';
import type * as Rsnapshot from './families/rsnapshot';
import type * as Samba from './families/samba';
import type * as Security from './families/security';
import type * as Storage from './families/storage';
import type * as Tls from './families/tls';
import type * as Windows from './families/windows';
import entries from './families.json';

export const FAMILIES = {
  ansible: () => import('./families/ansible'),
  apache: () => import('./families/apache'),
  caddy: () => import('./families/caddy'),
  cobol: () => import('./families/cobol'),
  cups: () => import('./families/cups'),
  directory: () => import('./families/directory'),
  docker: () => import('./families/docker'),
  forge: () => import('./families/forge'),
  ha: () => import('./families/ha'),
  iac: () => import('./families/iac'),
  ibmi: () => import('./families/ibmi'),
  inbound: () => import('./families/inbound'),
  jq: () => import('./families/jq'),
  k8s: () => import('./families/k8s'),
  lftp: () => import('./families/lftp'),
  libvirt: () => import('./families/libvirt'),
  luks: () => import('./families/luks'),
  mariadb: () => import('./families/mariadb'),
  nut: () => import('./families/nut'),
  objects: () => import('./families/objects'),
  openbao: () => import('./families/openbao'),
  postfix: () => import('./families/postfix'),
  postgres: () => import('./families/postgres'),
  prometheus: () => import('./families/prometheus'),
  rhel: () => import('./families/rhel'),
  rsnapshot: () => import('./families/rsnapshot'),
  samba: () => import('./families/samba'),
  security: () => import('./families/security'),
  storage: () => import('./families/storage'),
  tls: () => import('./families/tls'),
  windows: () => import('./families/windows'),
};
export type Family = keyof typeof FAMILIES;

interface Hooks {
  ansible: typeof Ansible.HOOKS;
  apache: typeof Apache.HOOKS;
  caddy: typeof Caddy.HOOKS;
  cobol: typeof Cobol.HOOKS;
  cups: typeof Cups.HOOKS;
  directory: typeof Directory.HOOKS;
  docker: typeof Docker.HOOKS;
  forge: typeof Forge.HOOKS;
  ha: typeof Ha.HOOKS;
  iac: typeof Iac.HOOKS;
  ibmi: typeof Ibmi.HOOKS;
  inbound: typeof Inbound.HOOKS;
  jq: typeof Jq.HOOKS;
  k8s: typeof K8s.HOOKS;
  lftp: typeof Lftp.HOOKS;
  libvirt: typeof Libvirt.HOOKS;
  luks: typeof Luks.HOOKS;
  mariadb: typeof Mariadb.HOOKS;
  nut: typeof Nut.HOOKS;
  objects: typeof Objects.HOOKS;
  openbao: typeof Openbao.HOOKS;
  postfix: typeof Postfix.HOOKS;
  postgres: typeof Postgres.HOOKS;
  prometheus: typeof Prometheus.HOOKS;
  rhel: typeof Rhel.HOOKS;
  rsnapshot: typeof Rsnapshot.HOOKS;
  samba: typeof Samba.HOOKS;
  security: typeof Security.HOOKS;
  storage: typeof Storage.HOOKS;
  tls: typeof Tls.HOOKS;
  windows: typeof Windows.HOOKS;
}

/** A family command's entry without its implementation (families.json). */
export type Entry = Omit<Command, 'launch'>;
/** Each family command: its family and its entry. */
export const FAMILY_COMMANDS = entries as unknown as Record<string, [Family, Entry]>;

const registered = new Map<Family, { commands: Record<string, Command>; hooks: object }>();

/** Called by a family's module when it loads. */
export function registerFamily<F extends Family>(name: F, commands: Record<string, Command>, hooks: Hooks[F]) {
  registered.set(name, { commands, hooks });
}

export const familyLoaded = (name: Family) => registered.has(name);

/** A loaded family's commands, with their implementation (tests, npm run catalogue). */
export const familyCommands = (name: Family): Record<string, Command> => registered.get(name)?.commands ?? {};

/** Loads a family (once); a failed download (offline) can be tried again. */
export const loadFamily = (name: Family): Promise<void> => (registered.has(name) ? Promise.resolve() : FAMILIES[name]().then(() => undefined));

/** A family's hooks; NeedsLoading while it isn't loaded. */
export function family<F extends Family>(name: F): Hooks[F] {
  const r = registered.get(name);
  if (!r) throw new NeedsLoading(`family ${name}`, () => loadFamily(name));
  return r.hooks as Hooks[F];
}

/**
 * A family's hooks if it is loaded: for a question only its stories' machines
 * can answer yes to (is this URL the forge's?). Not loaded, no machine of
 * theirs is in play.
 */
export const familyIfLoaded = <F extends Family>(name: F): Hooks[F] | undefined => registered.get(name)?.hooks as Hooks[F] | undefined;

/** A family command's implementation; NeedsLoading while its family isn't loaded. */
export function familyCommand(name: string): Command {
  const [f] = FAMILY_COMMANDS[name];
  const c = registered.get(f)?.commands[name];
  if (!c) throw new NeedsLoading(`family ${f}`, () => loadFamily(f));
  return c;
}

// What may come before a command on its line: sudo, env, nohup… and their options.
const WRAPPERS = new Set(['sudo', 'env', 'nohup', 'time', 'exec', 'command', 'nice', 'ionice', 'xargs', 'watch', 'timeout']);

/**
 * The families whose commands a command line runs: a word in a command's
 * place (after sudo, env, a variable…), not an argument (`man kubectl` reads
 * the entry, which needs no family).
 */
export function commandFamilies(line: string): Family[] {
  const out = new Set<Family>();
  for (const part of line.split(/\$\(|[;&|()`{}]|\b(?:then|do|else)\b/)) {
    const words = part.trim().split(/\s+/);
    let i = 0;
    while (i < words.length && (/^\w+=/.test(words[i]) || WRAPPERS.has(words[i]) || (i > 0 && /^(-|\d)/.test(words[i])))) i++;
    const name = words[i] ?? '';
    if (Object.hasOwn(FAMILY_COMMANDS, name)) out.add(FAMILY_COMMANDS[name][0]);
  }
  return [...out];
}

/** The families a command line names, not loaded yet (game.ts loads them before running it). */
export const familiesNamed = (line: string): Family[] => commandFamilies(line).filter((f) => !registered.has(f));
